 Certainly! Here's a JavaScript function that uses regular expressions and string manipulation to switch the order of adjectives in a given sentence:

```javascript
function switchAdjectiveOrder(sentence) {
  const wordList = sentence.split(' '); // Split the sentence into an array of words
  let adjectives = []; // Initialize an empty array to store the adjectives
  let nounIndex = -1; // Initialize the index of the first noun in the sentence

  for (let i = 0; i < wordList.length; i++) {
    const word = wordList[i];

    // Check if the word is an adjective using a list of common English adjectives
    if (isAdjective(word)) {
      adjectives.unshift(word); // Add the adjective to the beginning of the array
      continue;
    }

    // Find the index of the first noun in the sentence
    if (nounIndex === -1 && isNoun(word)) {
      nounIndex = i;
    }
  }

  // Reconstruct the sentence with the switched adjective order
  const newWordList = [];
  newWordList.push(...adjectives); // Add all adjectives before the noun
  newWordList.push(wordList[nounIndex]); // Add the noun after the adjectives
  newWordList.push(...wordList.slice(nounIndex + 1)); // Add the remaining words after the noun

  return newWordList.join(' ') + '.'; // Join the array back into a sentence and add a period at the end

  function isAdjective(word) {
    const adjectivesList = ['beautiful', 'green', 'lovely', 'red', 'happy', 'big', 'small']; // Add more adjectives as needed
    return adjectivesList.includes(word.toLowerCase());
  }

  function isNoun(word) {
    const nounsList = ['trees', 'park']; // Add more nouns as needed
    return nounsList.includes(word.toLowerCase());
  }
}

