Create a new sketch in Arduino IDE and paste the following code into it:

```cpp
#include <FastLED.h>

// Define the number of LEDs in the strip
#define NUM_LEDS 60

CRGB leds[NUM_LEDS];

const int buttonPin = D1; // Button pin
int currentLed = 0; // Current LED index

void setup() {
  Serial.begin(9600);
  FastLED.addLeds<WS2812B, NUM_LEDS, GRB>(leds, NUM_LEDS);
  pinMode(buttonPin, INPUT_PULLUP);
}

void loop() {
  if (digitalRead(buttonPin) == LOW) {
    currentLed++;
    if (currentLed > NUM_LEDS - 1) currentLed = 0; // Reset when reaching the end

    // Fade in the next LED with rainbow color
    leds[currentLed].setRGB(255, 0, 0); // Red
    leds[currentLed].fadeTo(50, 255, 10); // Fade

